"""Non-box witness extraction: find the certifying 2x2 minor of determinant one."""

from typing import Iterable, List, Optional, Sequence, Tuple

Cell = Tuple[int, int]


def find_non_box_witness(cells: Iterable[Cell]) -> Optional[Tuple[Cell, Cell, Cell]]:
    """Return ((a,b), (a',b'), (a,b')) violating the rectangle rule, or None.

    R is a combinatorial box iff (a,b), (a',b') in R implies (a,b') in R.  The
    returned triple is exactly the data the rigidity proof consumes: the two
    members of R and the missing crossover cell.  Cost: O(|R|^2).
    """
    s = set(cells)
    for (a, b) in s:
        for (ap, bp) in s:
            if (a, bp) not in s:
                return ((a, b), (ap, bp), (a, bp))
    return None


def certifying_minor(cells: Iterable[Cell]) -> Optional[List[List[float]]]:
    """The 2x2 block of the indicator matrix exposed by a non-box witness.

    Rows are indexed by (a, a'), columns by (b, b'); the block always has the
    shape [[1, 0], [m, 1]] with m in {0, 1}, hence determinant 1 and rank 2.
    """
    w = find_non_box_witness(cells)
    if w is None:
        return None
    s = set(cells)
    (a, b), (ap, bp), _ = w
    return [[1.0, 0.0],
            [1.0 if (ap, b) in s else 0.0, 1.0]]


def is_box(cells: Sequence[Cell]) -> bool:
    """True iff R is a combinatorial box, i.e. the product of its projections."""
    return find_non_box_witness(cells) is None
